/** Mutate actual indexed columns and their unkeyed audit outside a caller transaction.
 * The retained keyed proof, grant and counters deliberately stay byte-exact. */
function dc_keyed_index_damage(string $case,string $kind,array $row,array $changes):void {
    global $dns,$writes,$sent;
    $tableName=provider_directory_indexing_controls_tables()[$kind];
    foreach(array_keys($changes) as $column)if(!in_array($column,['id','package_id','disposition'],true))throw new LogicException('Unexpected fixture column.');
    $changedId=array_key_exists('id',$changes)?rtrim($changes['id'],' '):$row['id'];
    $set=implode(',',array_map(static fn($column)=>$column.'=?',array_keys($changes)));
    $restore=array_map(static fn($column)=>$row[$column],array_keys($changes));
    $detail='Directory listing change '.$kind.' '.$row['id'].' '.provider_directory_indexing_digest(provider_directory_indexing_controls_values($kind,$row));
    $audit=one('SELECT * FROM '.table('audit').' WHERE action=? AND detail=?',['provider.directory_indexing_control_'.$kind,$detail]);
    $before=[$dns,$writes,$sent,dc_count('provider_directory_changes'),dc_count('provider_operation_grants'),dc_count('provider_operations'),dc_count('audit')];
    $counts=array_map('provider_directory_indexing_controls_counter',['request','terminal','check']);
    try{
        dc_ok('Actual indexed '.$case.' row mutation occurs',query('UPDATE '.table($tableName).' SET '.$set.' WHERE id=?',[...array_values($changes),$row['id']])->rowCount()===1);
        $changed=one('SELECT * FROM '.table($tableName).' WHERE id=?',[$changedId]);
        dc_ok('Intended '.$case.' stored identity and indexed values changed',$changed!==null&&$changed['id']===$changedId&&(!isset($changes['disposition'])||$changed['disposition']===$changes['disposition']));
        $changedDetail='Directory listing change '.$kind.' '.$changed['id'].' '.provider_directory_indexing_digest(provider_directory_indexing_controls_values($kind,$changed));
        dc_ok('Actual unkeyed '.$case.' audit is recomputed',query('UPDATE '.table('audit').' SET detail=? WHERE id=?',[$changedDetail,$audit['id']])->rowCount()===1);
        dc_ok('Original keyed '.$case.' proof and counts remain untouched',$changed['proof']===$row['proof']&&array_map('provider_directory_indexing_controls_counter',['request','terminal','check'])===$counts);
        dc_deny_message('Keyed '.$case.' index tamper cannot admit a new approval',fn()=>dc_change(),'Directory listing change proof needs recovery.');
        dc_deny_message('Keyed '.$case.' index tamper cannot release current projection',fn()=>dc_view(),'Directory listing change proof needs recovery.');
        dc_ok('Keyed '.$case.' refusal creates no grant audit DNS read or write',[$dns,$writes,$sent,dc_count('provider_directory_changes'),dc_count('provider_operation_grants'),dc_count('provider_operations'),dc_count('audit')]===$before);
    }finally{
        query('UPDATE '.table($tableName).' SET '.$set.' WHERE id=?',[...$restore,$changedId]);
        query('UPDATE '.table('audit').' SET detail=? WHERE id=?',[$audit['detail'],$audit['id']]);
    }
    dc_ok('Exact '.$case.' restoration preserves source and readiness',one('SELECT * FROM '.table($tableName).' WHERE id=?',[$row['id']])===$row&&one('SELECT * FROM '.table('audit').' WHERE id=?',[$audit['id']])===$audit&&provider_directory_indexing_controls_ready());
}
